"use client";
import { useMemo, useState } from "react";

export default function LogsSearch({ logs }) {
  const [query, setQuery] = useState("");
  const filtered = useMemo(() => logs.filter((log) => JSON.stringify([log.action, log.user?.name, log.user?.email, log.event?.name, log.event?.slug, log.ip, log.metadata]).toLowerCase().includes(query.toLowerCase())), [logs, query]);
  return <section className="mt-7 overflow-hidden rounded-2xl border border-slate-200 bg-white"><div className="border-b p-4"><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search user, event, IP, or action…" className="w-full rounded-xl border border-slate-200 px-4 py-3 outline-none focus:border-[#0c796b]" /></div><div className="overflow-x-auto"><table className="w-full min-w-[850px] text-left text-sm"><thead className="bg-slate-50 text-xs uppercase text-slate-500"><tr>{["Time","Action","Administrator","Event","IP","Details"].map((h) => <th key={h} className="px-5 py-4">{h}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{filtered.map((log) => <tr key={log.id}><td className="whitespace-nowrap px-5 py-4 text-slate-500">{new Date(log.createdAt).toLocaleString()}</td><td className="px-5 py-4 font-bold">{log.action.replaceAll("_"," ")}</td><td className="px-5 py-4">{log.user?.name || "System"}<span className="block text-xs text-slate-400">{log.user?.email}</span></td><td className="px-5 py-4">{log.event?.name || "—"}<span className="block text-xs text-slate-400">{log.event?.slug}</span></td><td className="px-5 py-4 font-mono text-xs">{log.ip || "—"}</td><td className="max-w-xs truncate px-5 py-4 text-xs text-slate-500">{log.metadata ? JSON.stringify(log.metadata) : "—"}</td></tr>)}</tbody></table></div>{!filtered.length && <p className="p-10 text-center text-slate-500">No matching logs.</p>}</section>;
}
